// Traduz o evento de dominio na mensagem que a pessoa vai ler.
//
// Aqui e a BORDA DE APRESENTACAO: e o unico lugar do sistema que converte UTC
// para o horario local. O banco guarda UTC e o envelope transporta UTC com 'Z'
// (ver iso_utc em 0011); se a conversao acontecesse antes, o mesmo evento
// sairia com offset diferente dependendo de quem o emitiu.

const FUSO = $env.FUSO_PADRAO || 'America/Sao_Paulo';

function quando(iso) {
  const d = new Date(iso);
  const data = new Intl.DateTimeFormat('pt-BR', {
    timeZone: FUSO, day: '2-digit', month: '2-digit', weekday: 'short',
  }).format(d);
  const hora = new Intl.DateTimeFormat('pt-BR', {
    timeZone: FUSO, hour: '2-digit', minute: '2-digit', hour12: false,
  }).format(d);
  return { data, hora };
}

// Telefone brasileiro em E.164 sem '+'. Numero de 10 digitos NAO e
// necessariamente fixo: pode ser celular antigo sem o nono digito. Classifica
// pelo primeiro digito do numero local antes de mexer — apagar ou inserir
// digito as cegas perde parte da base.
function e164(bruto) {
  if (!bruto) return null;
  let d = String(bruto).replace(/\D+/g, '');
  if (d.startsWith('00')) d = d.slice(2);
  if (d.length >= 12 && d.startsWith('55')) return d;
  if (d.startsWith('55') && d.length === 11) d = d.slice(2);
  if (d.length === 11 || d.length === 10) {
    const local = d.slice(2);
    const primeiro = local[0];
    if (local.length === 8 && ['9', '8', '7', '6'].includes(primeiro)) {
      // celular antigo de 8 digitos: ganha o 9
      d = d.slice(0, 2) + '9' + local;
    }
    return '55' + d;
  }
  if (d.length === 13 && d.startsWith('55')) return d;
  return null;
}

const saida = [];

for (const item of $input.all()) {
  const ev = item.json;
  const d = ev.dados || {};
  const prof = d.profissional || {};
  const cli = d.cliente || {};
  const serv = d.servico || {};
  const loja = d.barbearia || {};

  let template = null;
  let variaveis = {};
  let destino = null;
  let canal = prof.canal === 'email' ? 'email' : 'whatsapp';

  const t = quando(d.inicio_em);
  const telCliente = e164(cli.telefone);
  const telProf = e164(prof.telefone);

  if (ev.evento === 'agendamento.criado') {
    template = 'novo_agendamento_barbeiro';
    variaveis = {
      profissional: prof.nome,
      cliente: cli.nome,
      servico: serv.nome,
      data: t.data,
      hora: t.hora,
      telefone_cliente: telCliente || 'nao informado',
      loja: loja.nome,
    };
  } else if (ev.evento === 'agendamento.cancelado') {
    template = 'agendamento_cancelado_barbeiro';
    variaveis = {
      profissional: prof.nome, cliente: cli.nome,
      servico: serv.nome, data: t.data, hora: t.hora,
    };
  } else if (ev.evento === 'agendamento.remarcado') {
    const antes = d.inicio_em_antigo ? quando(d.inicio_em_antigo) : null;
    template = 'agendamento_remarcado_barbeiro';
    variaveis = {
      profissional: prof.nome, cliente: cli.nome, servico: serv.nome,
      data: t.data, hora: t.hora,
      antes: antes ? `${antes.data} ${antes.hora}` : 'horario anterior',
    };
  } else if (ev.evento === 'agendamento.confirmado') {
    template = 'agendamento_confirmado_barbeiro';
    variaveis = {
      profissional: prof.nome, cliente: cli.nome,
      servico: serv.nome, data: t.data, hora: t.hora,
    };
  }

  destino = canal === 'whatsapp' ? telProf : prof.email;

  // Evento que nao tem mensagem associada, ou que nao tem para onde ir, e
  // marcado como entregue de proposito: deixar ele na fila faria o poller
  // tentar para sempre e o painel de 'eventos presos' encher de ruido, que e o
  // que faz um painel de saude parar de ser olhado.
  const entregavel = Boolean(template && destino);

  saida.push({
    json: {
      evento_id: ev.id,
      owner_id: ev.owner_id,
      evento: ev.evento,
      entregavel,
      motivo_nao_entregavel: entregavel
        ? null
        : (!template ? 'evento sem mensagem para o barbeiro' : 'profissional sem telefone nem e-mail'),
      canal,
      destino,
      template,
      variaveis,
      // A chave de dedupe descreve O QUE a mensagem e, nunca quando ela saiu.
      // Com timestamp na chave, a reentrega geraria chave nova e o dedupe nao
      // deduplicaria nada.
      chave_dedupe: `${ev.evento}:${d.appointment_id}`,
    },
  });
}

return saida;
